/// Exact syntax usable by a source-backed peerage alias context.
pub(crate) struct PeerageName {
    spelling: String,
    bridge: Option<PeerageBridge>,
}

pub(crate) struct PeerageBridge {
    style: String,
    full_style: String,
    personal_name: String,
